 </head>
 <body>
   <main id="app"></main>

   <script>
     const fields = [
       {
         id: "fullName",
         name: "fullName",
         label: "Full name",
         type: "text",
         placeholder: "Alex Morgan",
         required: true,
         autocomplete: "name",
         error: "Enter your full name."
       },
       {
         id: "email",
         name: "email",
         label: "Email address",
         type: "email",
         placeholder: "alex@example.com",
         required: true,
         autocomplete: "email",
         error: "Enter a valid email address."
       },
       {
         id: "phone",
         name: "phone",
         label: "Phone number",
         type: "tel",
         placeholder: "+1 555 123 4567",
         required: false,
         autocomplete: "tel",
         helper: "Optional. Use an international or local format, such as +1 555 123 4567.",
         error: "Enter a valid phone number or leave this field blank."
       }
     ];

     function SupportIntro() {
       return `
         <section class="support-intro" aria-labelledby="support-title">
           <span class="eyebrow">Support team</span>
           <h1 id="support-title">How can we help?</h1>
           <p>Send our product support team your contact details and we will route your request to the right specialist.</p>
         </section>
       `;
     }

     function FormField(field) {
       const requiredMarker = field.required ? ' <span class="required" aria-hidden="true">*</span>' : "";
       const requiredAttribute = field.required ? "required" : "";
       const helperMarkup = field.helper
         ? `<p class="helper-text" id="${field.id}-helper">${field.helper}</p>`
         : "";
       const describedBy = [
         field.helper ? `${field.id}-helper` : "",
         `${field.id}-error`
       ].filter(Boolean).join(" ");

       return `
         <div class="form-field" data-field="${field.id}">
           <label for="${field.id}">${field.label}${requiredMarker}</label>
           <input
             id="${field.id}"
             name="${field.name}"
             type="${field.type}"
             placeholder="${field.placeholder}"
             autocomplete="${field.autocomplete}"
             aria-describedby="${describedBy}"
             aria-invalid="false"
             ${requiredAttribute}
           >
           ${helperMarkup}
           <p class="error-message" id="${field.id}-error" role="alert">${field.error}</p>
         </div>
       `;
     }

     function ContactForm() {
       return `
         <form class="contact-form" id="supportForm" novalidate>
           <h2 class="form-heading">Contact support</h2>
           <p class="form-subtitle">Fields marked with <span class="required">*</span> are required.</p>
           ${fields.map(FormField).join("")}
           <button class="submit-button" type="submit">Submit request</button>
           <p class="success-message" id="successMessage" role="status">Thanks! Your support request is ready to send.</p>
         </form>
       `;
     }

     function App() {
       return `
         <div class="page-shell">
           <article class="support-card">
             ${SupportIntro()}
             ${ContactForm()}
           </article>
         </div>
       `;
     }

     function isValidEmail(value) {
       return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
     }

     function isValidPhone(value) {
       return value === "" || /^\+?[0-9\s().-]{7,20}$/.test(value);
     }

     function validateField(input) {
       const value = input.value.trim();
       let isValid = true;

       if (input.required && value === "") {
         isValid = false;
       } else if (input.type === "email" && !isValidEmail(value)) {
         isValid = false;
       } else if (input.type === "tel" && !isValidPhone(value)) {
         isValid = false;
       }

       input.setAttribute("aria-invalid", String(!isValid));
       input.closest(".form-field").classList.toggle("has-error", !isValid);
       return isValid;
     }

     function attachValidation() {
       const form = document.querySelector("#supportForm");
       const successMessage = document.querySelector("#successMessage");
       const inputs = Array.from(form.querySelectorAll("input"));

       inputs.forEach((input) => {
         input.addEventListener("blur", () => validateField(input));
         input.addEventListener("input", () => {
           successMessage.classList.remove("is-visible");
           if (input.getAttribute("aria-invalid") === "true") {
             validateField(input);
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         const isFormValid = inputs.map(validateField).every(Boolean);
         successMessage.classList.toggle("is-visible", isFormValid);
       });
     }

     document.querySelector("#app").innerHTML = App();
     attachValidation();
   </script>
 </body>
 </html>

